import net.runelite.api.events.InteractingChanged;
import net.runelite.client.Notifier;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.xptracker.XpTrackerService;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.overlay.OverlayManager;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import static org.mockito.ArgumentMatchers.any;
import org.mockito.Mock;
import static org.mockito.Mockito.doNothing;
import static org.mockito.Mockito.lenient;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;
import org.mockito.junit.MockitoJUnitRunner;

@RunWith(MockitoJUnitRunner.class)
public class RandomEventAnalyticsPluginTest
{
	@Mock
	@Bind
	Client client;
	@Mock
	@Bind
	ConfigManager configManager;
	@Mock
	@Bind
	RandomEventAnalyticsConfig config;
	@Mock
	@Bind
	OverlayManager overlayManager;
	@Mock
	@Bind
	RandomEventAnalyticsOverlay overlay;
	@Mock
	@Bind
	RandomEventAnalyticsPanel panel;
	@Mock
	@Bind
	RandomEventAnalyticsLocalStorage localStorage;
	@Mock
	@Bind
	TimeTracking timeTracking;
	@Mock
	@Bind
	ChatMessageManager chatMessageManager;
	@Mock
	@Bind
	XpTrackerService xpTrackerService;

	@Mock
	@Bind
	ClientToolbar clientToolbar;

	@Mock
	@Bind
	Notifier notifier;

	@Bind
	Clock clock = Clock.systemUTC();

	@Inject
	RandomEventAnalyticsPlugin plugin;

	@Before
	public void before() {
		Guice.createInjector(BoundFieldModule.of(this)).injectMembers(this);
		mockLocalStorage();
	}

	@Test
	public void testAddsRandomEventWhenValidNPCInteractionChanged()
	{
		doNothing().when(panel).addRandom(any());
		plugin.setPanel(panel);

		final Player player = getMockedPlayer();
		when(client.getLocalPlayer()).thenReturn(player);
		when(client.getTickCount()).thenReturn(10);

		NPC npc1 = getMockedNPC(NpcID.BEE_KEEPER_6747);
		interactingChanged(npc1, player);

		verify(localStorage, times(1)).addRandomEventRecord(any());
		verify(panel, times(1)).addRandom(any());
		verify(timeTracking, times(1)).setRandomEventSpawned();
	}

	@Test
	public void testDoesNotAddOtherPlayersRandoms()
	{
		final Player player = getMockedPlayer();
		when(client.getLocalPlayer()).thenReturn(player);

		Player otherPlayer = getMockedPlayer();
		NPC npc1 = getMockedNPC(NpcID.BEE_KEEPER_6747);
		interactingChanged(npc1, otherPlayer);

		verify(localStorage, times(0)).addRandomEventRecord(any());
		verify(panel, times(0)).addRandom(any());
		verify(timeTracking, times(0)).setRandomEventSpawned();
	}

	private void mockLocalStorage() {
		when(localStorage.addRandomEventRecord(any())).thenReturn(true);
	}

	private NPC getMockedNPC(int npcID) {
		final NPC npc = mock(NPC.class);
		when(npc.getWorldLocation()).thenReturn(new WorldPoint(0, 0, 0));
		when(npc.getLocalLocation()).thenReturn(new LocalPoint(0,0));
		when(npc.getName()).thenReturn("MockedNPCName");
		when(npc.getCombatLevel()).thenReturn(1);
		when(npc.getId()).thenReturn(npcID);
		return npc;
	}

	private Player getMockedPlayer() {
		final Player player = mock(Player.class);
		when(player.getWorldLocation()).thenReturn(new WorldPoint(0, 0, 0));
		when(player.getLocalLocation()).thenReturn(new LocalPoint(0,0));
		when(player.getCombatLevel()).thenReturn(126);
		return player;
	}

	private void interactingChanged(final Actor source, final Actor target) {
		lenient().when(source.getInteracting()).thenReturn(target);
		plugin.onInteractingChanged(new InteractingChanged(source, target));
	}
}

package com.randomEventAnalytics;

import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * A custom panel that renders the 2-hour random event spawn window as a pseudo-progress bar.
 *
 * <p>The bar spans from the window anchor (t = 0) to +2 hours, with a midpoint tick at +1h
 * indicating when the eligible window opens. A vertical cursor moves left-to-right as time
 * passes. The fill colour is driven by {@link WindowState}.
 *
 * <p>Must be updated from the EDT via {@link #update(long, WindowState)}.
 */
public class SpawnWindowBar extends JPanel
{
	/**
	 * Total window duration: 2 hours in seconds.
	 */
	private static final int TOTAL_WINDOW_SECONDS = TimeTracking.SECONDS_IN_AN_HOUR * 2;

	private static final int TRACK_HEIGHT = 12;
	private static final int TICK_OVERHANG = 4; // extra pixels the midpoint tick extends below the track
	private static final int LABEL_GAP = 2;

	/**
	 * Dark background for the pre-window half of the track.
	 */
	private static final Color TRACK_BG = new Color(35, 35, 35);
	/**
	 * Slightly lighter background for the +1h–+2h eligible zone.
	 */
	private static final Color TRACK_WINDOW_BG = new Color(50, 50, 50);
	private static final Color TICK_COLOR = new Color(120, 120, 120);
	private static final Color LABEL_COLOR = ColorScheme.LIGHT_GRAY_COLOR;
	private static final Color CURSOR_COLOR = Color.WHITE;

	/**
	 * Alpha applied to the bar fill when in NO_DATA state (estimated from first login).
	 */
	private static final float NO_DATA_ALPHA = 0.55f;

	private long secondsSinceAnchor = 0;
	private WindowState state = WindowState.NO_DATA;

	public SpawnWindowBar()
	{
		setOpaque(false);
	}

	/**
	 * Updates the bar with new timing data and schedules a repaint.
	 * Must be called from the EDT.
	 *
	 * @param secondsSinceAnchor seconds elapsed since the window anchor instant
	 * @param state              the current {@link WindowState}
	 */
	public void update(long secondsSinceAnchor, WindowState state)
	{
		this.secondsSinceAnchor = secondsSinceAnchor;
		this.state = state;
		repaint();
	}

	@Override
	public Dimension getPreferredSize()
	{
		FontMetrics fm = getFontMetrics(FontManager.getRunescapeSmallFont());
		int h = TRACK_HEIGHT + TICK_OVERHANG + LABEL_GAP + fm.getHeight() + 2;
		return new Dimension(super.getPreferredSize().width, h);
	}

	@Override
	public Dimension getMaximumSize()
	{
		// Allow the bar to stretch horizontally but never expand vertically beyond its preferred height.
		return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		super.paintComponent(g);
		Graphics2D g2 = (Graphics2D) g.create();
		try
		{
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

			int w = getWidth();
			int trackY = 0;
			int midX = w / 2;

			// Cursor fraction in [0, 1]; clamped so it never exceeds right edge visually
			double fraction = Math.min(1.0, secondsSinceAnchor / (double) TOTAL_WINDOW_SECONDS);
			int cursorX = (int) (fraction * w);

			// ── Background track ─────────────────────────────────────────────
			g2.setColor(TRACK_BG);
			g2.fillRect(0, trackY, w, TRACK_HEIGHT);

			// Slightly lighter zone for the eligible window (+1h → +2h)
			g2.setColor(TRACK_WINDOW_BG);
			g2.fillRect(midX, trackY, w - midX, TRACK_HEIGHT);

			// ── Elapsed fill ──────────────────────────────────────────────────
			Composite originalComposite = g2.getComposite();
			if (state == WindowState.NO_DATA)
			{
				// Semi-transparent fill to signal estimation rather than confirmed data
				g2.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, NO_DATA_ALPHA));
			}

			if (state == WindowState.OVERDUE)
			{
				// Full bar coloured to signal the window has passed
				g2.setColor(state.barFillColor);
				g2.fillRect(0, trackY, w, TRACK_HEIGHT);
			}
			else if (cursorX > 0)
			{
				g2.setColor(state.barFillColor);
				g2.fillRect(0, trackY, cursorX, TRACK_HEIGHT);
			}

			g2.setComposite(originalComposite);

			// ── +1h midpoint tick ─────────────────────────────────────────────
			g2.setColor(TICK_COLOR);
			g2.setStroke(new BasicStroke(1f));
			g2.drawLine(midX, trackY, midX, trackY + TRACK_HEIGHT + TICK_OVERHANG);

			// ── Cursor line ───────────────────────────────────────────────────
			// Not drawn when overdue (cursor is off the right edge) or at position 0
			if (state != WindowState.OVERDUE && cursorX > 0 && cursorX < w)
			{
				g2.setColor(CURSOR_COLOR);
				g2.setStroke(new BasicStroke(2f));
				g2.drawLine(cursorX, trackY, cursorX, trackY + TRACK_HEIGHT);
			}

			// ── Labels ────────────────────────────────────────────────────────
			g2.setFont(FontManager.getRunescapeSmallFont());
			FontMetrics fm = g2.getFontMetrics();
			int labelY = trackY + TRACK_HEIGHT + TICK_OVERHANG + LABEL_GAP + fm.getAscent();

			g2.setColor(LABEL_COLOR);

			g2.drawString("Last Spawn", 0, labelY);

			String midLabel = "+1h";
			int midLabelW = fm.stringWidth(midLabel);
			g2.drawString(midLabel, midX - midLabelW / 2, labelY);

			String endLabel = "+2h";
			int endLabelW = fm.stringWidth(endLabel);
			g2.drawString(endLabel, w - endLabelW, labelY);
		}
		finally
		{
			g2.dispose();
		}
	}
}

package com.randomEventAnalytics;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.PanelComponent;

public class RandomEventAnalyticsOverlay extends Overlay
{
	private static final int BACKGROUND_ALPHA = 126;

	private final RandomEventAnalyticsConfig config;
	private final PanelComponent panelComponent = new PanelComponent();
	private final TimeTracking timeTracking;
	private final Client client;

	@Inject
	private RandomEventAnalyticsOverlay(RandomEventAnalyticsConfig config,
										TimeTracking timeTracking, Client client)
	{
		setPosition(OverlayPosition.ABOVE_CHATBOX_RIGHT);
		this.config = config;
		this.timeTracking = timeTracking;
		this.client = client;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.enableOverlay())
		{
			return null;
		}

		panelComponent.getChildren().clear();
		panelComponent.setPreferredSize(new Dimension(ComponentConstants.STANDARD_WIDTH, 0));

		final boolean hasAnchor = timeTracking.getWindowAnchor() != null;
		final boolean windowExpired = timeTracking.isWindowExpired();
		final boolean windowOpen = timeTracking.isWindowOpen();
		final boolean inInstance = client.isInInstancedRegion();
		final boolean noEventsYet = timeTracking.getLastRandomSpawnInstant() == null;
		final WindowState windowState = WindowState.from(hasAnchor, windowExpired, windowOpen, inInstance,
			noEventsYet);

		if (config.enableOverlayBackground())
		{
			final Color base = windowState.badgeColor;
			panelComponent.setBackgroundColor(new Color(base.getRed(), base.getGreen(), base.getBlue(),
				BACKGROUND_ALPHA));
		}
		else
		{
			panelComponent.setBackgroundColor(ComponentConstants.STANDARD_BACKGROUND_COLOR);
		}

		// Tick line: 5-minute eligibility countdown.
		final int nextTickSeconds = timeTracking.getNextRandomEventEstimation();
		panelComponent.getChildren().add(LineComponent.builder()
			.left("Next Check:")
			.right(RandomEventAnalyticsUtil.formatSeconds(Math.abs(nextTickSeconds)))
			.build());

		// When the window is open, show the Latest countdown; otherwise show Earliest.
		final String windowLabel;
		final String windowText;
		if (windowExpired)
		{
			windowLabel = "Earliest:";
			windowText = "overdue";
		}
		else if (windowOpen)
		{
			windowLabel = "Latest:";
			windowText = RandomEventAnalyticsUtil.formatSeconds((int) timeTracking.getSecondsUntilLatest());
		}
		else
		{
			windowLabel = "Earliest:";
			windowText = RandomEventAnalyticsUtil.formatSeconds((int) timeTracking.getSecondsUntilEarliest());
		}
		panelComponent.getChildren().add(LineComponent.builder()
			.left(windowLabel)
			.right(windowText)
			.build());

		return panelComponent.render(graphics);
	}
}

package com.randomEventAnalytics;

import com.randomEventAnalytics.localstorage.RandomEventRecord;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Font;
import java.awt.GridLayout;
import java.text.SimpleDateFormat;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import javax.swing.border.LineBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

public class RandomEventRecordBox extends JPanel
{
	private final RandomEventAnalyticsPanel panel;
	private final RandomEventRecord randomEvent;

	private final JLabel spawnedTimeLabel = new JLabel();

	RandomEventRecordBox(RandomEventAnalyticsPanel panel, RandomEventRecord randomEvent)
	{
		this(panel, randomEvent, true);
	}

	RandomEventRecordBox(RandomEventAnalyticsPanel panel, RandomEventRecord randomEvent, boolean isConfirmed)
	{
		this.randomEvent = randomEvent;
		this.panel = panel;
		buildRandomEventPanel(randomEvent, isConfirmed);
	}

	private String buildToolTip(RandomEventRecord record)
	{
		String spawnedTime = panel.longTimeFormat.format(record.spawnedTime);
		String data =
			"<html> " + "NPC ID: " + record.npcInfoRecord.npcId + "<br>\u0394 Event Time: " + RandomEventAnalyticsUtil.formatSeconds(record.secondsSinceLastRandomEvent) + "<br>Spawned Time: " + spawnedTime;
		data += "<br>PlayerLocal: <p style=\"font-size: 0.95em\">" + "(X: " + record.playerInfoRecord.localX + " , Y: "
			+ record.playerInfoRecord.localY + ")</p>";
		data += "Intervals: ";
		if (record.intervalsSinceLastRandom > 0)
		{
			data += record.intervalsSinceLastRandom + "<p style=\"font-size: 0.95em\">(" + record.intervalsSinceLastRandom * 5 + " minutes)</p>";
		} else {
			data += "Record has no data<br>";
		}
		data += "World: <p style=\"font-size: 0.95em\">" + "(X: " + record.playerInfoRecord.worldX + " , Y: " + record.playerInfoRecord.worldY + " , P: " + record.playerInfoRecord.worldPlane + ")</p>";
		data += "</html>";
		return data;

	}

	public RandomEventRecord getRandomEvent()
	{
		return randomEvent;
	}

	private JPanel buildRandomEventPanel(RandomEventRecord record, boolean isConfirmed)
	{
		JLabel randomName = new JLabel(record.npcInfoRecord.npcName);
		spawnedTimeLabel.setText(panel.shortTimeFormat.format(record.spawnedTime));

		this.setBorder(new EmptyBorder(10, 10, 10, 10));
		this.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		this.setLayout(new BorderLayout());

		JPanel randomInfo = new JPanel();
		randomInfo.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		randomInfo.setLayout(new GridLayout(2, 1));
		randomInfo.setBorder(new EmptyBorder(0, 10, 0, 0));

		randomName.setFont(FontManager.getRunescapeBoldFont());
		spawnedTimeLabel.setFont(FontManager.getRunescapeSmallFont());
		randomInfo.add(randomName);
		randomInfo.add(spawnedTimeLabel);

		this.add(new JLabel(RandomEventAnalyticsUtil.getNPCIcon(record.npcInfoRecord.npcId)), BorderLayout.WEST);
		this.add(randomInfo);
		this.setToolTipText(buildToolTip(record));
		if (!isConfirmed)
		{
			this.add(buildConfirmationPanel(record));
		}
		update();
		return this;
	}

	private JPanel buildConfirmationPanel(RandomEventRecord record)
	{
		JPanel confirmationPanel = new JPanel();
		confirmationPanel.setBorder(new EmptyBorder(0, 0, 0, 0));
		confirmationPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		confirmationPanel.setLayout(new BorderLayout());

		JPanel labelPanel = new JPanel();
		labelPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		labelPanel.setLayout(new GridLayout(2, 1, 5, 0)); // Stack labels vertically
		labelPanel.setBorder(new EmptyBorder(0, 0, 10, 0));
		JLabel confirmRandomLabel = new JLabel("Is this your random event?");
		JLabel altConfirmLabel = new JLabel("<html>You may also click the plant to confirm.</html>");
		altConfirmLabel.setFont(FontManager.getRunescapeSmallFont());

		labelPanel.add(confirmRandomLabel);
		labelPanel.add(altConfirmLabel);

		// Button Panel
		JPanel buttonPanel = new JPanel();
		buttonPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		buttonPanel.setLayout(new GridLayout(1, 2));

		JButton confirm = new JButton("\u2713");
		confirm.setFont(new Font(Font.DIALOG, Font.PLAIN, 12));
		confirm.setBorder(new LineBorder(Color.GREEN, 1));
		confirm.setForeground(Color.GREEN);
		confirm.addActionListener((e) -> {
			SwingUtilities.invokeLater(() -> {
				panel.eventRecordBoxUpdated(this, true);
			});
		});

		JButton cancel = new JButton("\u2717");
		cancel.setFont(new Font(Font.DIALOG, Font.PLAIN, 12));
		cancel.setBorder(new LineBorder(Color.RED, 1));
		cancel.setForeground(Color.RED);
		cancel.addActionListener((e) -> {
			panel.eventRecordBoxUpdated(this, false);
		});

		buttonPanel.add(confirm);
		buttonPanel.add(cancel);

		confirmationPanel.add(labelPanel, BorderLayout.NORTH);
		confirmationPanel.add(buttonPanel, BorderLayout.SOUTH);

		return confirmationPanel;
	}

	void update() {
		// TODO: We'll eventually want to update the rest of the values, but
		//		for now just the spawned time (when config changed)
		spawnedTimeLabel.setText(panel.shortTimeFormat.format(randomEvent.spawnedTime));
		this.setToolTipText(buildToolTip(randomEvent));
	}
}

